<template>
  <div class="search">
    <input
      @focus="isFocus(true)"
      @blur="isFocus(false)"
      v-model="filterInput"
      @input="filter($event)"
      type="text"
      autocomplete="off"
      spellcheck="false"
      placeholder="Filter"
      :disabled="disableInput"
    />
  </div>
  <div class="list">
    <table>
      <colgroup>
        <col span="1" style="width: 7%;" />
        <col span="2" style="width: 75%;" />
      </colgroup>

      <thead>
        <tr>
          <th style="text-align: center;">LID</th>
          <th>NAME</th>
          <th style="text-align: center;">LEVEL</th>
          <th style="text-align: center;">PING</th>
        </tr>
      </thead>
      <tbody>
        <tr v-for="player in filteredPlayers" :key="player">
          <td :style="{ color: player.color ? player.color : '' }" style="text-align: center;">
            {{ player.lid }}
          </td>
          <td :style="{ color: player.color ? player.color : '' }">{{ player.name }}</td>
          <td :style="{ color: player.color ? player.color : '' }" style="text-align: center;">
            {{ player.level }}
          </td>
          <td :style="{ color: player.color ? player.color : '' }" style="text-align: center;">
            {{ player.ping }}
          </td>
        </tr>
      </tbody>
    </table>
  </div>
  <div v-if="players.length < 1" class="error">
    <template v-if="type === 1">
      Global is empty???
    </template>
    <template v-else-if="type === 2">
      Lobby is empty.
    </template>
    <template v-else-if="stats.squad === -1 && type === 3">
      You are not in a squad.
    </template>
    <template v-else-if="stats.squad >= 0 && type === 3">
      Your squad is empty.
    </template>
  </div>
  <div class="spacer"></div>
</template>

<script>
export default {
  name: "FilterTab",
  props: ["players", "stats", "type"],
  data() {
    return {
      disableInput: false,
      filterInput: "",
      filteredPlayers: [],
    };
  },
  methods: {
    // eslint-disable-next-line no-unused-vars
    isFocus(value) {
      // eslint-disable-next-line no-undef
      mp.trigger("ScoreboardToggleTyping", value);
    },
    filter(event) {
      let input = event.target.value.replace(/\s/g, "");
      if (input.length < 1) return (this.filteredPlayers = this.players);
      this.filteredPlayers = this.players
        .filter((player) => player.name.toUpperCase().includes(input.toUpperCase()))
        .sort(function(a, b) {
          return a - b;
        });
    },
  },
  watch: {
    players: {
      handler: function(players) {
        let input = this.filterInput.replace(/\s/g, "");
        if (input.length > 0) {
          this.filteredPlayers = players.filter((player) => player.name.toUpperCase().includes(input.toUpperCase()));
        } else {
          this.filteredPlayers = players.sort(function(a, b) {
            return a - b;
          });
        }
      },
    },
  },
  mounted() {
    this.filteredPlayers = this.players;
  },
};
</script>

<style scoped lang="scss">
.error {
  background: rgba($score-bg, 0.5);
  display: flex;
  justify-content: center;
  align-items: center;
  color: rgba(241, 241, 241, 0.9);
  font-size: 15px;
  padding-top: 5px;
}

.search {
  background: rgba($score-bg, 0.5);
  padding: 5px;
  border-bottom: 1.5px solid rgba(241, 241, 241, 0.7);

  input {
    width: 100%;
    border-radius: 2px;
    border: none;
    height: 25px;
    padding: 5px;
    font-size: 15px;
    background: rgba(lighten($score-bg, 50%), 0.4);
    color: rgba(lighten($score-bg, 70%), 0.7);

    &::placeholder {
      color: rgba(lighten($score-bg, 70%), 0.3);
    }

    &:focus {
      outline: none;
    }
  }
}

.list {
  max-height: 400px;
  overflow-y: auto;

  table {
    width: 100%;
    background: rgba($score-bg, 0.5);

    th {
      text-align: left;
      font-size: 12px;
      color: rgba(241, 241, 241, 0.9);
      padding: 12px 8px;
      border-bottom: 1.5px solid rgba(241, 241, 241, 0.7);
    }

    td {
      padding: 4px 8px;
      color: rgba(241, 241, 241, 0.9);
      word-break: break-all;
    }
  }
}

.spacer {
  background: rgba($score-bg, 0.5);
  border-bottom-left-radius: 10px;
  border-bottom-right-radius: 10px;
  height: 10px;
}
</style>
