<template>
  <div>
    <div id="speedo" :class="['speedo-gauge-container car-speedo', { speedoFugitive: fugitive }]" :key="reSpeedo">
      <span class="value-text">km/h</span>
    </div>
  </div>
</template>

<script>
let Gauge = require("svg-gauge");

export default {
  name: "Speedometer",
  props: ["fugitive"],
  data() {
    return {
      speed: 1,
      maxspeed: 170,
      speedo: null,
      reSpeedo: true,
    };
  },
  watch: {
    speed(value) {
      this.speedo.setValueAnimated(value > 999 ? 999 : value, 0);
    },
    maxspeed() {
      //force rerender of element
      this.reSpeedo = !this.reSpeedo;

      //wait a little and set the maxspeed
      setTimeout(() => {
        this.speedo = Gauge(document.getElementById("speedo"), {
          max: this.maxspeed,
          dialStartAngle: 90,
          dialEndAngle: 0,
          value: this.speed,
        });
      }, 50);
    },
  },
  mounted() {
    let that = this;
    this.$nextTick(function() {
      that.speedo = Gauge(document.getElementById("speedo"), {
        max: that.maxspeed,
        dialStartAngle: 90,
        dialEndAngle: 0,
        value: that.speed,
      });
    });
  },
};
</script>

<style scoped lang="scss">
div {
  margin-bottom: -20px;
  margin-right: -15px;
}
</style>

<style lang="scss">
.speedoFugitive > .gauge .value {
  stroke: $orange !important;
  filter: drop-shadow(0 0 3px $orange) !important;
}

/* ------ Default Style ---------- */
.speedo-gauge-container {
  width: 170px;
  height: 170px;
}

.speedo-gauge-container > .label {
  position: absolute;
  right: 0;
  top: 0;
  display: inline-block;
  background: rgba(0, 0, 0, 0.5);
  font-family: monospace;
  font-size: 0.8em;
  padding: 5px 10px;
}

.speedo-gauge-container > .gauge .dial {
  stroke: #334455;
  stroke-width: 2;
  fill: rgba(0, 0, 0, 0);
  stroke-linecap: round;
}

.speedo-gauge-container > .gauge .value {
  stroke: $blue;
  stroke-width: 2;
  fill: rgba(0, 0, 0, 0);
  stroke-linecap: round;
  filter: drop-shadow(0 0 3px $blue);
}

/* ----- Alternate Style ----- */
.speedo-gauge-container.car-speedo > .gauge .dial {
  stroke: rgba(lighten($foreground, 20%), 0.5);
  filter: drop-shadow(0 0 3px lighten($foreground, 20%));
  stroke-width: 10;
}

.speedo-gauge-container.car-speedo > .gauge .value {
  transition: stroke 0.4s;
  stroke: $blue;
  stroke-dasharray: none;
  stroke-width: 10;
}

//value
.speedo-gauge-container.car-speedo > .gauge .value-text {
  transition: fill 0.4s;
  font-family: "Nunito", sans-serif;
  fill: #f1f1f1;
  transform: translate3d(26%, 20%, 0);
  display: inline-block;
  font-weight: bolder;
  font-size: 1.7em;
  text-shadow: 0 0 5px lighten($foreground, 20%);
}

//small value
.speedo-gauge-container.car-speedo .value-text {
  transition: color 0.4s;
  font-family: "Nunito", sans-serif;
  color: #f1f1f1;
  text-shadow: 0 0 5px lighten($foreground, 20%);
  position: absolute;
  bottom: -10%;
  right: -6%;
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  font-size: 1.8em;
}
</style>
